// Scan /data/chatin for new request captures since the last cron tick,
// parse the intent + action verb, hand each item downstream for dispatch.
//
// Each captured chat message lives in /data/chatin/*.json with shape:
//   { captured_at, source, intent, normalized: { sender, channel, text, ... }, ... }
//
// We only route items whose intent is 'change-request' or 'app-change-request'
// or 'question' — captures and tests stay logged but don't fire actions.
//
// We use /data/chatin/_router_state.json to remember the last processed
// timestamp, so we don't re-fire actions on every cron tick.

const fs = require('fs');
const path = require('path');

const CHATIN_DIR = '/data/chatin';
const STATE_FILE = path.join(CHATIN_DIR, '_router_state.json');
const ROUTED_DIR = path.join(CHATIN_DIR, '_routed');
fs.mkdirSync(ROUTED_DIR, { recursive: true });

let state = { last_processed: null };
try {
  state = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
} catch (_) { /* first run */ }

const since = state.last_processed ? new Date(state.last_processed).getTime() : 0;
const now = Date.now();

const files = fs.readdirSync(CHATIN_DIR)
  .filter(f => f.endsWith('.json') && !f.startsWith('_'));

const routables = [];
for (const f of files) {
  const full = path.join(CHATIN_DIR, f);
  let rec;
  try {
    rec = JSON.parse(fs.readFileSync(full, 'utf8'));
  } catch (_) { continue; }
  const capturedAt = rec.captured_at ? new Date(rec.captured_at).getTime() : 0;
  if (capturedAt <= since) continue;
  if (!rec.intent) continue;
  if (!['change-request', 'app-change-request', 'question'].includes(rec.intent)) continue;

  // Anti-noise filter per the binding 'Data attached to solution or KPI'
  // principle (Darrell 2026-06-02): skip records with empty/undefined text.
  // An item with no text content has no actionable request to route; firing
  // the Fallback 'Need review' message for these produces pure noise.
  const _text = (rec.normalized && rec.normalized.text) || '';
  const _sender = (rec.normalized && rec.normalized.sender) || '';
  if (!_text || _text.trim() === '' || _text === 'undefined') continue;
  if (!_sender || _sender.trim() === '' || _sender === 'undefined' || _sender === 'unknown') continue;

  const text = (rec.normalized && rec.normalized.text) || '';
  const sender = (rec.normalized && rec.normalized.sender) || 'unknown';
  const channel = (rec.normalized && rec.normalized.channel) || 'unknown';

  // Action detection — pattern-match on the first verb after intent.
  // Examples we handle in this first version:
  //   send <text> to <user>      → action: dm,  target: <user>
  //   dm <user> <text>           → action: dm,  target: <user>
  //   notify <user> <text>       → action: dm,  target: <user>
  //   email <addr> <text>        → action: email, target: <addr>
  //   anything else              → action: queue-for-review (post to chat as a question)
  let action = 'queue-for-review';
  let target = null;
  let body = text;

  const lower = text.toLowerCase();
  const dmMatch = lower.match(/^(?:send|dm|notify|message|tell|ask)\s+@?([a-z][a-z0-9_-]{1,32})\s+(.+)/i);
  if (dmMatch) {
    action = 'dm';
    target = dmMatch[1];
    body = dmMatch[2];
  } else {
    const sendToMatch = lower.match(/^send\s+(.+?)\s+to\s+@?([a-z][a-z0-9_-]{1,32})/i);
    if (sendToMatch) {
      action = 'dm';
      target = sendToMatch[2];
      body = sendToMatch[1];
    } else {
      const emailMatch = lower.match(/^email\s+(\S+@\S+)\s+(.+)/i);
      if (emailMatch) {
        action = 'email';
        target = emailMatch[1];
        body = emailMatch[2];
      }
    }
  }

  routables.push({
    source_file: f,
    captured_at: rec.captured_at,
    sender: sender || 'unknown',
    channel: channel || 'unknown',
    raw_text: text || '',
    intent: rec.intent,
    action,
    target,
    body: body || text || ''
  });
}

// Update state file so the next tick only sees newer items.
fs.writeFileSync(STATE_FILE, JSON.stringify({ last_processed: new Date(now).toISOString() }, null, 2));

if (routables.length === 0) {
  return [{ json: { skipped: true, reason: 'no-new-routable-items', cursor: state.last_processed } }];
}

// Fan out one item per route so downstream nodes can handle each independently.
return routables.map(r => ({ json: r }));

