// Move the processed source file to /data/chatin/_routed/ so we keep an
// audit trail of what got dispatched and don't re-dispatch on cursor
// regressions.
const fs = require('fs');
const path = require('path');
const src = '/data/chatin/' + $json.source_file;
const dst = '/data/chatin/_routed/' + $json.source_file;
try { fs.renameSync(src, dst); } catch (e) { return [{ json: { warn: 'archive failed', err: String(e), file: $json.source_file } }]; }
return [{ json: { archived: dst, action: $json.action, target: $json.target } }];
